mapper.update:
UPDATE attractions
SET ratingSum = IFNULL(ratingSum, 0) + #{rating}
WHERE no = #{attractionNo}

UPDATE attractions
SET ratingSum = IFNULL(ratingSum, 0) - #{rating}
WHERE no = #{attractionNo}

UPDATE attractions
SET reviewCount = IFNULL(reviewCount, 0) + 1
WHERE no = #{attractionNo}

UPDATE attractions
SET reviewCount = IFNULL(reviewCount, 0) - 1
WHERE no = #{attractionNo}
